function exportExcel(){try{const snapshot=clone(data);snapshot.settings.lastBackup=new Date().toISOString();const wb=workbookFor(snapshot);XLSX.writeFile(wb,`跑者公開版備份_${today()}_${String(new Date().getHours()).padStart(2,'0')}${String(new Date().getMinutes()).padStart(2,'0')}.xlsx`,{compression:true});if(!writeBlocked){persist(snapshot);render();}if(state.modal?.kind==='settings')openSettings();toast('已產生 Excel 備份，請確認檔案已下載保存。');}catch(e){showError(e.message);}}
