function template(t){if(!obj(t)||!id(t.id)||!str(t.name,200)||!Object.hasOwn(types,t.type)||(t.runClass!=null&&!['',...runClasses,'法克雷特'].includes(t.runClass))||!Array.isArray(t.resultFields)||t.resultFields.some(x=>!runFields.some(y=>y[0]===x))||!Array.isArray(t.exercises)||t.exercises.length>100||!Array.isArray(t.custom)||t.custom.length>100)fail();for(const e of t.exercises)exercise(e,false);for(const f of t.custom)if(!obj(f)||!id(f.id)||!str(f.label,200)||!['text','textarea','number','select'].includes(f.type)||!['plan','result','both'].includes(f.stage)||!Array.isArray(f.options)||f.options.length>50||f.options.some(o=>!str(o,1000)))fail();}
