if(!obj(d)||d.version!==VERSION||!Array.isArray(d.records)||d.records.length>50000||!obj(d.daily)||!Array.isArray(d.templates)||d.templates.length>500||!Array.isArray(d.races)||d.races.length>1000||!obj(d.settings)||!ids(d.records)||!ids(d.templates)||!ids(d.races))fail();d.templates.forEach(template);
for(const r of d.records){if(!obj(r)||!id(r.id)||!date(r.date)||!str(r.title,200)||!Object.hasOwn(types,r.type)||!Object.hasOwn(statuses,r.status)||!str(r.createdAt,100)||!Array.isArray(r.tags)||r.tags.some(t=>!str(t,1000))||!values(r.customPlan))fail();template(r.snapshot);if(r.result){const v=r.result;if(!obj(v)||!str(v.notes)||!str(v.reason)||!str(v.time,100)||!str(v.pace,100)||!numeric(v.distance,0,1000)||!numeric(v.heart,0,250)||!numeric(v.rpe,0,10)||!numeric(v.temperature,-60,65)||!numeric(v.humidity,0,100)||!numeric(v.ascent,0,100000)||!numeric(v.descent,0,100000)||!values(v.custom)||!Array.isArray(v.exercises)||v.exercises.length>100)fail();v.exercises.forEach(e=>exercise(e,true));validateLaps(v);}}
for(const [s,v] of Object.entries(d.daily))if(!date(s)||!obj(v)||!numeric(v.feeling,1,5)||!numeric(v.sleep,0,100)||!numeric(v.soreness,0,10)||!numeric(v.hrv,0,1000)||!str(v.body,1000))fail();
